import{_ as p,r as n,o as l,c as o,e as s,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Partial 列 - October CMS - 3.x","titleTemplate":false,"description":"列表列","frontmatter":{"subtitle":"列表列","shortname":"Partial"},"headers":[{"level":2,"title":"使用视图模板","slug":"使用视图模板","link":"#使用视图模板","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/element/lists/column-partial.md","filePath":"3.x/zh-cn/element/lists/column-partial.md"}'),i={name:"3.x/zh-cn/element/lists/column-partial.md"};function u(d,a,k,m,h,g){const t=n("pre-heading"),e=n("post-heading");return l(),o("div",null,[s(t),a[0]||(a[0]=c("h1",null,"Partial 列",-1)),s(e),a[1]||(a[1]=r(`<p><code>partial</code> 列将使用部件或视图文件渲染列内容。<code>path</code> 值可以引用部件视图文件，否则将使用列名称作为部件名称。视图路径的默认范围是控制器的视图路径。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> content_column
</code></pre></div><p>支持以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>path</strong></td><td><a href="./../../extend/system/views.html">部件视图文件</a>或<a href="./../../extend/services/response-view.html">视图模板代码</a>的路径，默认为以 <strong>column_</strong> 为前缀的列名称。</td></tr></tbody></table></div><p>当 <code>path</code> 设置为非限定文件名（不包含目录路径和扩展名的文件名）时，源路径将被确定为模型或控制器目录。以下示例将在 <strong>../models/mymodel/_column_for_content.php</strong> 或 <strong>../controllers/mycontroller/_column_for_content.php</strong> 中查找部件文件。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> column_for_content
</code></pre></div><p>您可以指定完全限定的 <code>path</code> 来访问模型或控制器目录之外的部件。这对于在不同定义之间共享部件非常有用。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> $/acme/blog/partials/_content_column.php
</code></pre></div><p>在部件内部以下变量可用。</p><ul><li><code>$value</code> 是默认的单元格值</li><li><code>$record</code> 是用于单元格的模型</li><li><code>$column</code> 是已配置的类对象 <code>Backend\\Classes\\ListColumn</code></li></ul><p>以下是 <strong>_content_column.php</strong> 文件的一些示例内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$record</span><span class="token operator">-&gt;</span><span class="token property">is_active</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token function">e</span><span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="使用视图模板"><a href="#使用视图模板" class="header-anchor">#</a> 使用视图模板</h2><p>您可以将视图模板代码作为 <code>path</code> 传递，以访问插件内部的视图服务模板。以下代码将在路径 <strong>plugins/acme/blog/views/listcolumns/content.php</strong> 中找到。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">content</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
    <span class="token key atrule">type</span><span class="token punctuation">:</span> partial
    <span class="token key atrule">path</span><span class="token punctuation">:</span> acme.blog<span class="token punctuation">:</span><span class="token punctuation">:</span>listcolumns.content
</code></pre></div><div class="custom-block tip"><p>路径必须包含 <code>::</code> 字符才能激活视图服务。</p></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../../extend/system/views.html">渲染控制器视图</a></li><li><a href="./../../extend/services/response-view.html">响应与视图服务</a></li></ul></div>`,18))])}const v=p(i,[["render",u]]);export{y as __pageData,v as default};
